{

"kind": "propose",
"summary": "Increase memory limit to prevent OOM kills",
"hypotheses": [
  {
    "root_cause_class": "memory_limit_too_low",
    "summary": "Container app's memory limit is insufficient for its workload",
    "supporting": ["oom_killed_current_revision", "memory_data_available", "container_logs_tail"],
    "contradicting": ["earlier_revision_healthy"],
    "missing": [],
    "status": "supported"
  },
  {
    "root_cause_class": "node_memory_pressure",
    "summary": "Node memory pressure causing OOM kills despite adequate container limits",
    "supporting": ["evicted_for_node_memory"],
    "contradicting": ["memory_data_available"],
    "missing": [],
    "status": "refuted"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "inventory",
    "uid": "uid-deployment-inventory"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "2Gi"
        }
      }
    }
  },
  "expected_effect": "Prevent OOM kills by allocating sufficient memory",
  "rationale": "Container logs confirm OOM kills (exit code 137) and suggest memory limits are too low. The logs explicitly recommend increasing the memory limit to 2Gi to avoid cgroup OOM kills.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-pod_states", "ev-rollout_history"],
  "cited_predicates": ["oom_killed_current_revision", "memory_data_available", "killed_during_startup"]
}
}
